// Derives a slim, English-only client bundle from the full server-side
// server/data/esco-taxonomy.json — strips German labels and everything not
// needed for synchronous, client-side label matching (job listings are
// matched client-side without a network round trip; only resume parsing
// goes through the server's async Groq-fallback-enabled path — see
// resumeParserService.ts and README.md's ESCO section for why).
//
// Emitted as a .ts module (export default), NOT a .json file: a plain JSON
// import needs an explicit `with { type: 'json' }` import attribute under
// Node's own ESM loader (which this repo's test runner uses directly,
// unlike the Vite-bundled app, which handles bare JSON imports itself) —
// emitting .ts sidesteps that entirely and works identically in both.
//
// Run: node scripts/build-esco-client-bundle.mjs (after build-esco-taxonomy.mjs)

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const SERVER_TAXONOMY = path.join(ROOT, 'server', 'data', 'esco-taxonomy.json');
const CUSTOM_ALIASES = path.join(ROOT, 'server', 'data', 'esco-custom-aliases.json');
const OUT_FILE = path.join(ROOT, 'src', 'data', 'escoTaxonomyClient.data.ts');

const full = JSON.parse(readFileSync(SERVER_TAXONOMY, 'utf8'));
const aliasesRaw = JSON.parse(readFileSync(CUSTOM_ALIASES, 'utf8'));
const { _comment, ...aliasesByUri } = aliasesRaw;

// esco-custom-aliases.json pins each alias to a skill's stable ESCO Concept
// URI (see its own header comment) — resolved to this build's skill:N id
// here, same as server/services/escoTaxonomyService.js does at server
// startup, so the client bundle never ships an alias pointing at the wrong
// skill just because build-esco-taxonomy.mjs ran with a different category
// filter at some point. Fails loudly rather than silently dropping/
// mis-resolving a URI that isn't in this taxonomy build.
const skillUriToId = new Map(Object.entries(full.skills).map(([id, s]) => [s.escoUri, id]));
const customAliases = {};
const unresolvedAliases = [];
for (const [phrase, uri] of Object.entries(aliasesByUri)) {
  const id = skillUriToId.get(uri);
  if (id) {
    customAliases[phrase] = id;
  } else {
    unresolvedAliases.push(`"${phrase}" -> ${uri}`);
  }
}
if (unresolvedAliases.length > 0) {
  console.error(`ERROR: ${unresolvedAliases.length} alias(es) in ${CUSTOM_ALIASES} point to a URI not present in ${SERVER_TAXONOMY}:`);
  for (const line of unresolvedAliases) console.error(`  ${line}`);
  console.error('Run scripts/build-esco-taxonomy.mjs first (it validates this same file) or fix the affected alias entries.');
  process.exit(1);
}

const skills = {};
for (const [id, s] of Object.entries(full.skills)) {
  skills[id] = { label: s.label, altLabels: s.altLabels, categories: s.categories };
}

const occupations = {};
for (const [id, o] of Object.entries(full.occupations)) {
  occupations[id] = { label: o.label, altLabels: o.altLabels, iscoGroup: o.iscoGroup, essentialSkillIds: o.essentialSkillIds };
}

const output = {
  meta: { generatedAt: new Date().toISOString(), skillCount: Object.keys(skills).length, occupationCount: Object.keys(occupations).length },
  skills,
  occupations,
  customAliases,
};

// Deliberately NOT `as const` — a literal-type annotation over ~1.7MB of
// string data would force TypeScript to infer a distinct literal type per
// string value, which is genuinely slow/memory-heavy at this size. A plain
// value (typed by escoTaxonomyClient.ts's own interfaces at the import
// site) checks just as safely without that cost.
const fileContents =
  '// AUTO-GENERATED by scripts/build-esco-client-bundle.mjs — do not edit by hand.\n' +
  '// Run `node scripts/build-esco-taxonomy.mjs && node scripts/build-esco-client-bundle.mjs` to regenerate.\n' +
  `export default ${JSON.stringify(output)};\n`;

writeFileSync(OUT_FILE, fileContents);
console.log(`Wrote ${OUT_FILE}`);
